/** 5000-seat scheduling diagnostic; preserves the earlier wall-frame result. */
import {createRequire} from 'node:module';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {createServer} from 'node:http';
import {resolve,join,extname} from 'node:path';
import {createHash} from 'node:crypto';
const require=createRequire(new URL('../web/package.json',import.meta.url)),{chromium}=require('playwright');
const root=resolve(new URL('..',import.meta.url).pathname),out=resolve(process.argv[2]||'build/qa/browser');await mkdir(out,{recursive:true});
const fixturePath=process.argv[3]||'build/qa/canonical-final-fixtures',seatCount=Number(process.argv[4]||5000);
const kernel=await readFile(join(root,'web/dist/venue_layout_kernel.js'));
const server=createServer(async(req,res)=>{if(req.url==='/blank'){res.setHeader('Content-Type','text/html');res.end('<!doctype html><script src="/web/dist/venue_layout_kernel.js"></script>');return;}try{const p=join(root,new URL(req.url,'http://localhost').pathname);res.setHeader('Content-Type',({'.js':'text/javascript','.json':'application/json'}[extname(p)]||'application/octet-stream'));res.end(await readFile(p));}catch{res.statusCode=404;res.end();}});await new Promise(r=>server.listen(0,'127.0.0.1',r));const base=`http://127.0.0.1:${server.address().port}`;
const browser=await chromium.launch({headless:true});let result;
try{const context=await browser.newContext({viewport:{width:1440,height:900}});await context.route('**/*',r=>r.request().url().startsWith(base)?r.continue():r.abort());const p=await context.newPage();await p.goto(`${base}/blank`);result=await p.evaluate(async({fixturePath,seatCount})=>{
 const[{mount},document,resources]=await Promise.all([import('/web/src/index.js'),fetch(`/${fixturePath}/corpus-${seatCount}.document.json`).then(r=>r.json()),fetch('/assets/layout_fonts/fixtures.json').then(r=>r.json())]);const host=window.document.createElement('div');host.style.cssText='width:1400px;height:800px';window.document.body.append(host);const viewer=mount(host,{document,resources}),id=document.nodes.find(n=>n.kind==='seat').id;await new Promise(requestAnimationFrame);await new Promise(requestAnimationFrame);
 const rafIntervals=[],wallCallbackIntervals=[],updateCpu=[],wheelCpu=[];let previousTimestamp,previousWall,steps=0;
 await new Promise(resolve=>{const tick=timestamp=>{const wall=performance.now();if(previousTimestamp!==undefined){rafIntervals.push(timestamp-previousTimestamp);wallCallbackIntervals.push(wall-previousWall);}previousTimestamp=timestamp;previousWall=wall;let t=performance.now();viewer.update({seatPresentation:{[id]:{selected:steps%2===0}}});updateCpu.push(performance.now()-t);t=performance.now();viewer.svg.dispatchEvent(new WheelEvent('wheel',{deltaY:steps%2?5:-5,clientX:400,clientY:300,bubbles:true,cancelable:true}));wheelCpu.push(performance.now()-t);steps++;if(steps<=120)requestAnimationFrame(tick);else resolve();};requestAnimationFrame(tick);});
 const p95=values=>[...values].sort((a,b)=>a-b)[Math.ceil(values.length*.95)-1];const issues=viewer.scene.issues;viewer.dispose();return{count:seatCount,samples:rafIntervals.length,rafTimestampP95Ms:p95(rafIntervals),wallCallbackP95Ms:p95(wallCallbackIntervals),patchCpuP95Ms:p95(updateCpu),wheelCpuP95Ms:p95(wheelCpu),missedFramesOver20ms:rafIntervals.filter(v=>v>20).length,rafTimestampIntervalsMs:rafIntervals,wallCallbackIntervalsMs:wallCallbackIntervals,issues,method:'120 successive RAF callback timestamp intervals with a public viewer state patch and DOM wheel event each callback; no startup samples omitted; CPU durations separate; earlier wall interaction measurement remains unchanged'};
 },{fixturePath,seatCount});await context.close();result.browser=browser.version();}
finally{await browser.close();await new Promise(r=>server.close(r));}
result.kernelSha256=createHash('sha256').update(kernel).digest('hex');result.sourceChangedDuringRun=!kernel.equals(await readFile(join(root,'web/dist/venue_layout_kernel.js')));result.rafTargetComparisonPrecisionMs=.000001;result.rafTargetPass=Math.round(result.rafTimestampP95Ms*1e6)/1e6<=16.7;await writeFile(join(out,'frame-timing.json'),JSON.stringify(result,null,2));console.log(`${seatCount} RAF timestamp p95 ${result.rafTimestampP95Ms.toFixed(3)}ms; wall callbacks ${result.wallCallbackP95Ms.toFixed(3)}ms; missed >20ms ${result.missedFramesOver20ms}/${result.samples}`);if(!result.rafTargetPass||result.sourceChangedDuringRun||result.issues.length)process.exitCode=1;
